// Nodo: Vacantes
// Obtiene el catalogo de vacantes con detalles desde PostgreSQL via /api/prompt-context

const dbData = $('Recibido desde Inicio').first().json._candidato || {};
const naveActual = String(dbData.nave_interes || '1').trim();
let apiBase = 'http://host.docker.internal:3001';
let empresaId = '';
try { if (typeof process !== 'undefined' && process.env && process.env.TCI_API_BASE) apiBase = process.env.TCI_API_BASE; } catch(e) {}
try { if (typeof $env !== 'undefined' && $env && $env.TCI_API_BASE) apiBase = $env.TCI_API_BASE; } catch(e) {}
try { if (typeof process !== 'undefined' && process.env && process.env.TCI_EMPRESA_ID) empresaId = process.env.TCI_EMPRESA_ID; } catch(e) {}
try { if (typeof $env !== 'undefined' && $env && $env.TCI_EMPRESA_ID) empresaId = $env.TCI_EMPRESA_ID; } catch(e) {}

let detalleTxt = "Informacion no disponible.";
let menuTxt = "";

try {
    const url = empresaId
        ? apiBase + '/api/prompt-context?empresa_id=' + empresaId
        : apiBase + '/api/prompt-context';
    const response = await fetch(url);
    if (response.ok) {
        const ctx = await response.json();
        detalleTxt = ctx.detalle_vacantes || detalleTxt;
        menuTxt = ctx.menu_vacantes || "";
    }
} catch(error) {
    console.log('Error consultando prompt-context:', error.message);
}

// Si el candidato ya tiene nave elegida, extraer solo esa seccion
if (naveActual && naveActual !== 'Pendiente') {
    const seccionMatch = detalleTxt.match(
        new RegExp('--- SUCURSAL ' + naveActual + ':.*?---\\n([\\s\\S]*?)(?=--- SUCURSAL|$)')
    );
    if (seccionMatch) {
        detalleTxt = seccionMatch[1].trim();
    }
}

for (const item of items) {
    item.json.detalle_vacantes = detalleTxt;
    item.json.menu_vacantes = menuTxt;
}

return items;

// 1. OBTENER EL JSON LIMPIO DE GEMINI
const item = $input.first();
const rawText = item.json.content?.parts?.[0]?.text || item.json.output || item.json.text || "{}";

const jsonMatch = rawText.match(/\{[\s\S]*\}/);
const cleanJson = jsonMatch ? jsonMatch[0] : rawText.replace(/```json|```/g, '').trim();

let datos = {};
try { datos = JSON.parse(cleanJson); } catch (e) { datos = {}; }

// 2. EXTRAER VARIABLES BÁSICAS
const tipo = (datos.tipo_documento || "GENERICO").toUpperCase();
const nombreOriginal = datos.nombre_completo || "Candidato";
const nombreLimpio = nombreOriginal
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9 ]/g, "")
    .replace(/\s+/g, "_");
const vacanteAnuncio = datos.vacante_anuncio || "General";

let telefono = $('Recibido desde Inicio').first().json._contacto.number;

// 3. RENOMBRAR ARCHIVO FÍSICO
let binaryData = {};
try { binaryData = $('DescargarMedia').first().binary; } catch(e) { binaryData = item.binary; }

if (binaryData) {
    const key = Object.keys(binaryData)[0];
    if (binaryData[key]) {
        const ext = (binaryData[key].fileExtension || "pdf").replace('.', '');
        binaryData[key].fileName = `${tipo}_${nombreLimpio}_${telefono}.${ext}`;
    }
}

let edadCalculada = null;
if (datos.fecha_nacimiento && datos.fecha_nacimiento !== "No visible" && datos.fecha_nacimiento !== "null") {
    const matchAno = datos.fecha_nacimiento.match(/\d{4}/);
    if (matchAno) {
        edadCalculada = (new Date().getFullYear() - parseInt(matchAno[0])).toString() + " años";
    }
}
let nombreWhatsApp = $('Recibido desde Inicio').first().json._webhook.body.payload._data?.notifyName || "Candidato";

// 4. LÓGICA DEL MENSAJE PARA SOFÍA (AI CHAT)
const dbData = $('Recibido desde Inicio').first().json._candidato || {};
let msgUsuario = datos.mensaje_usuario || ""; 

// 🚀 MAGIA: Rescatamos el texto del candidato que acompaña a la imagen
const captionUsuario = $('Recibido desde Inicio').first().json._webhook.body.payload.body || "";

if (!msgUsuario || msgUsuario === "null") {
    if (tipo === "SOLICITUD" && dbData.estado !== 'CV_RECIBIDO') {
        msgUsuario = "El candidato acaba de enviar la PRIMERA foto de su solicitud (frente). Agradécele e indícale que por favor envíe también la foto de la PARTE TRASERA para tener su expediente completo. Dile que si su solicitud solo tiene un lado o ya mandó ambas, responda 'Listo'.";
    } else if (tipo === "ANUNCIO") {
        // Armamos el contexto de la imagen + lo que escribió el usuario
        msgUsuario = `[SISTEMA: El candidato te envió una captura de pantalla del anuncio de la vacante: *${vacanteAnuncio}*.`;
        if (captionUsuario) {
            msgUsuario += ` Además, escribió este mensaje: "${captionUsuario}".`;
        }
        msgUsuario += ` OBLIGATORIO: Atiéndelo de forma natural, asume que le interesa esa vacante y muéstrale los detalles o pregúntale si quiere aplicar.]`;
    } else if (tipo === "INE") {
        if (dbData.datos_rfc) {
            msgUsuario = "[SISTEMA: AMBOS DOCUMENTOS COMPLETOS. El candidato entregó INE y RFC. Revisa INMEDIATAMENTE tu calendario y ofrécele fechas de entrevista.]";
        } else {
            msgUsuario = "[SISTEMA: El candidato entregó su INE, pero FALTA SU CONSTANCIA. Agradécele por el INE y pídele obligatoriamente su Constancia de Situación Fiscal (RFC). TIENES ESTRICTAMENTE PROHIBIDO AGENDAR CITA AÚN.]";
        }
    } else if (tipo === "CONSTANCIA") {
        if (dbData.datos_ine) {
            msgUsuario = "[SISTEMA: AMBOS DOCUMENTOS COMPLETOS. El candidato entregó INE y RFC. Revisa INMEDIATAMENTE tu calendario y ofrécele fechas de entrevista.]";
        } else {
            msgUsuario = "[SISTEMA: El candidato entregó su Constancia (RFC), pero FALTA SU INE. Agradécele por la Constancia y pídele obligatoriamente la foto frontal de su INE. TIENES ESTRICTAMENTE PROHIBIDO AGENDAR CITA AÚN.]";
        }
    } else if (tipo === "CV" || (tipo === "SOLICITUD" && dbData.estado === 'CV_RECIBIDO')) {
        if (!datos.correo) {
            msgUsuario = "[SISTEMA: CV Recibido. Pregunta ÚNICAMENTE: '¡Recibí tu documento y tu perfil está súper bien! 👏 Antes de continuar, ¿me podrías proporcionar tu correo electrónico, por favor? 📧']";
        } else {
            msgUsuario = "[SISTEMA: CV Recibido. Pregunta ÚNICAMENTE: '¡Recibí tu documento y tu perfil está súper bien! 👏 Antes de continuar, me gustaría hacerte una pregunta rápida: ¿Te encuentras laborando actualmente? 💼']";
        }
    } else {
        msgUsuario = "El candidato envió un documento. Confírmale de recibido de forma amable.";
    }
} else if (tipo === "ANUNCIO") {
    msgUsuario = `[SISTEMA: El candidato te envió una foto del anuncio de la vacante: *${vacanteAnuncio}*. Mensaje: "${captionUsuario}". Atiéndelo.]`;
}

// 4.5 VALIDACIÓN CRUZADA Y EVALUACIÓN DE DISCREPANCIA EN CURP
let identidadBloqueada = false;
let identidadMotivo = "";

function calcularDistanciaLevenshtein(a, b) {
    if (!a) return b ? b.length : 0;
    if (!b) return a.length;
    const matrix = [];
    for (let i = 0; i <= b.length; i++) matrix[i] = [i];
    for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
    for (let i = 1; i <= b.length; i++) {
        for (let j = 1; j <= a.length; j++) {
            if (b.charAt(i - 1) === a.charAt(j - 1)) {
                matrix[i][j] = matrix[i - 1][j - 1];
            } else {
                matrix[i][j] = Math.min(
                    matrix[i - 1][j - 1] + 1,
                    Math.min(matrix[i][j - 1] + 1, matrix[i - 1][j] + 1)
                );
            }
        }
    }
    return matrix[b.length][a.length];
}

function evaluarCurps(c1Raw, c2Raw) {
    if (!c1Raw || !c2Raw) return { tipo: 'OK' };
    const c1 = String(c1Raw).toUpperCase().replace(/[^A-Z0-9]/g, '');
    const c2 = String(c2Raw).toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (!c1 || !c2) return { tipo: 'OK' };

    if (c1 === c2) return { tipo: 'OK' };

    const dist = calcularDistanciaLevenshtein(c1, c2);
    const core1 = c1.substring(0, 10);
    const core2 = c2.substring(0, 10);
    const coreMatch = (core1.length === 10 && core2.length === 10 && core1 === core2);

    // Si la mayoría coincide pero hay una pequeña diferencia (1 o 2 caracteres por OCR borroso)
    if (dist <= 2 || coreMatch) {
        return { 
            tipo: 'REVISION_HUMANA', 
            distancia: dist,
            c1, 
            c2 
        };
    }

    // Discrepancia grave (distintas personas)
    return { 
        tipo: 'GRAVE', 
        distancia: dist,
        c1, 
        c2 
    };
}

let curpEval = { tipo: 'OK' };
if (tipo === "INE" && dbData.curp_rfc && datos.curp) {
    curpEval = evaluarCurps(datos.curp, dbData.curp_rfc);
} else if ((tipo === "CONSTANCIA" || tipo === "CSF" || tipo === "RFC") && dbData.curp_ine && datos.curp) {
    curpEval = evaluarCurps(datos.curp, dbData.curp_ine);
}

let curpIneSalida = tipo === "INE" ? (datos.curp || null) : null;
let curpRfcSalida = (tipo === "CONSTANCIA" || tipo === "CSF" || tipo === "RFC") ? (datos.curp || null) : null;

if (curpEval.tipo === 'REVISION_HUMANA') {
    identidadBloqueada = true;
    identidadMotivo = `Diferencia menor en la CURP: INE (${curpEval.c1}) vs Constancia (${curpEval.c2}), distancia de ${curpEval.distancia} caracter(es). Posible error de OCR por calidad de foto — requiere validación de un reclutador.`;
    msgUsuario = "[SISTEMA: Recibimos ambos documentos. Notamos una pequeña diferencia en la CURP, probablemente por la calidad de la foto. Un reclutador ya está revisando tus documentos y te confirmará en breve si puedes continuar. ¡Gracias por tu paciencia!]";
} else if (curpEval.tipo === 'GRAVE') {
    identidadBloqueada = true;
    identidadMotivo = `CURP totalmente distinta entre INE (${curpEval.c1}) y Constancia (${curpEval.c2}) — posible documento de otra persona. Requiere validación de un reclutador antes de continuar.`;
    msgUsuario = "[SISTEMA: Recibimos tus documentos, pero la CURP del INE y de la Constancia no coinciden. Un reclutador va a revisar tus documentos para confirmar tu identidad antes de continuar. Te avisaremos en cuanto lo revisen.]";
}

// 5. SALIDA
return {
    json: {
        nombre: nombreOriginal,
        telefono: telefono,
        tipo_origen: tipo,
        cv_manual: datos,
        experiencia: datos.experiencia || "",
        veredicto: datos.veredicto || null,
        motivo: datos.motivo || null,
        resumen_excel: datos.resumen_excel || null,
        fecha_nacimiento: datos.fecha_nacimiento || "No visible",
        vacante_anuncio: vacanteAnuncio,
        mensaje_usuario: msgUsuario,
        edad_calculada: edadCalculada,
        nombre_chat: nombreWhatsApp,
        correo: datos.correo || null,
        identidad_bloqueada: identidadBloqueada,
        identidad_motivo: identidadMotivo,
        curp_ine: curpIneSalida,
        curp_rfc: curpRfcSalida
    },
    binary: binaryData
};

