// 1. DATOS DEL CANDIDATO
const dbData = $('Recibido desde Inicio').first().json._candidato || {};
const naveActual = String(dbData.nave_interes || '').trim() || '1';
const vacante = String(dbData.vacante_interes || 'General').trim();

// 2. CARGAR RECLUTADOR_VACANTES desde la BD via API
let equipo = [];
const _debug = { api_key_present: false, fetch_status: null, fetch_error: null };
try {
    let apiBase = 'http://host.docker.internal:3001';
    let empresaId = '';
    let apiKey = '';
    try { if (typeof process !== 'undefined' && process.env && process.env.TCI_API_BASE) apiBase = process.env.TCI_API_BASE; } catch(e) {}
    try { if (typeof $env !== 'undefined' && $env && $env.TCI_API_BASE) apiBase = $env.TCI_API_BASE; } catch(e) {}
    try { if (typeof process !== 'undefined' && process.env && process.env.TCI_EMPRESA_ID) empresaId = process.env.TCI_EMPRESA_ID; } catch(e) {}
    try { if (typeof $env !== 'undefined' && $env && $env.TCI_EMPRESA_ID) empresaId = $env.TCI_EMPRESA_ID; } catch(e) {}
    try { if (typeof process !== 'undefined' && process.env && process.env.N8N_API_KEY) apiKey = process.env.N8N_API_KEY; } catch(e) {}
    try { if (typeof $env !== 'undefined' && $env && $env.N8N_API_KEY) apiKey = $env.N8N_API_KEY; } catch(e) {}
    _debug.api_key_present = !!apiKey;
    const apiUrl = empresaId
        ? apiBase + "/api/db/reclutador_vacantes?empresa_id=" + empresaId
        : apiBase + "/api/db/reclutador_vacantes";
    const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: apiUrl,
        headers: apiKey ? { 'x-api-key': apiKey } : {},
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
    });
    _debug.fetch_status = resp.statusCode;
    if (resp.statusCode >= 200 && resp.statusCode < 300) { equipo = Array.isArray(resp.body) ? resp.body : []; }
} catch (e) {
    _debug.fetch_error = String((e && e.message) || e);
    equipo = [{
        nombre: "Gerente de Reclutamiento",
        emoji: "🚨",
        telefono: "5213332012658",
        calendar_id: "talreclutamiento01@gmail.com",
        naves: ["1","2","3"],
        vacantes: []
    }];
}
_debug.equipo_count = equipo.length;

const gerente = equipo.find(r => r.nombre === 'Gerente de Reclutamiento') || equipo[equipo.length - 1] || {
    nombre: "Gerente de Reclutamiento",
    telefono: "5213332012658",
    calendar_id: "talreclutamiento01@gmail.com"
};

const defaultCalendar = (gerente.calendar_id && String(gerente.calendar_id).trim()) || "talreclutamiento01@gmail.com";

// 3. BUSCAR MATCHES: soporta comparación por ID de vacante, nombre de vacante y por nave/ID de nave
const cleanStr = (s) => s ? String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim() : '';
const vacanteClean = cleanStr(vacante);
const vacanteDesconocida = !vacanteClean || vacanteClean === 'GENERAL';

if (vacanteDesconocida) {
    return {
        json: {
            nombre_reclutador: "Equipo de Reclutamiento",
            telefono_reclutador: gerente.telefono || "5213323379399",
            calendar_id: defaultCalendar,
            vacante_detectada: vacante,
            nave_candidato: naveActual,
            grupo_turno: null,
            turno_total: 1,
            candidatos_turno: null,
            _debug: _debug
        }
    };
}

const matches = equipo.filter(r =>
    r.nombre !== gerente.nombre &&
    Array.isArray(r.vacantes) &&
    r.vacantes.length > 0 &&
    r.vacantes.some(v => {
        const vNombreClean = cleanStr(v.nombre);
        const vIdClean = cleanStr(v.id);
        const matchVacante = (vIdClean && vIdClean === vacanteClean) ||
                             (vNombreClean && vNombreClean === vacanteClean) ||
                             (vNombreClean && vacanteClean && (vNombreClean.includes(vacanteClean) || vacanteClean.includes(vNombreClean)));

        if (!matchVacante) return false;
        const navesVacante = v.naves || (v.nave ? [v.nave] : []);
        if (navesVacante.length === 0) return true;

        const naveClean = cleanStr(naveActual);
        if (!naveClean || naveClean === '1' || naveClean === 'GENERAL' || naveClean === 'PENDIENTE') return true;

        return navesVacante.some(n => {
            const nClean = cleanStr(n);
            return nClean === naveClean || nClean.includes(naveClean) || naveClean.includes(nClean);
        });
    })
);

// 4. FALLBACK: si nadie tiene la vacante específica → Gerente
const candidatos = matches.length > 0 ? matches : [gerente];

// 5. SI SOLO HAY 1 RECLUTADOR: salida directa
if (candidatos.length === 1) {
    const cand = candidatos[0];
    return {
        json: {
            nombre_reclutador: cand.nombre || "Equipo de Reclutamiento",
            telefono_reclutador: cand.telefono || "5213323379399",
            calendar_id: (cand.calendar_id && String(cand.calendar_id).trim()) || defaultCalendar,
            vacante_detectada: vacante,
            nave_candidato: naveActual,
            grupo_turno: null,
            turno_total: 1,
            candidatos_turno: null,
            _debug: _debug
        }
    };
}

// 6. MÚLTIPLES RECLUTADORES: preparar turno rotativo
const grupoKey = candidatos
    .map(r => r.nombre)
    .sort()
    .join('|')
    .substring(0, 100);

return {
    json: {
        vacante_detectada: vacante,
        nave_candidato: naveActual,
        grupo_turno: grupoKey,
        turno_total: candidatos.length,
        candidatos_turno: JSON.stringify(
            candidatos.map(r => ({
                nombre: r.nombre || "Reclutador",
                telefono: r.telefono || "5213323379399",
                calendar_id: (r.calendar_id && String(r.calendar_id).trim()) || defaultCalendar,
                emoji: r.emoji || '📅'
            }))
        ),
        _debug: _debug
    }
};
